const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function partnerWizard({step=1,draft={},user=null}={}){
 const field=(name,label,placeholder,max=300,area=false)=>`<label>${label}${area?`<textarea name="${name}" required minlength="3" maxlength="${max}" placeholder="${placeholder}">${esc(draft[name])}</textarea>`:`<input name="${name}" required minlength="3" maxlength="${max}" placeholder="${placeholder}" value="${esc(draft[name])}" ${name==='actor'?'pattern="[a-zA-Z0-9_-]{1,100}/[a-zA-Z0-9_-]{1,100}"':''}>`}</label>`;
 const fields=step===1?`${field('title','Как называется ваш продукт?','Например: мониторинг цен интернет-магазинов',120)}${field('audience','Кому он нужен?','Например: e-commerce-командам',300)}${field('description','Какую задачу он решает?','Какой результат получит покупатель и для чего сможет его использовать',1000,true)}<label>Категория<select name="category">${['Исследования','Лидогенерация','Рекламная аналитика','Соцсети','Поиск и SEO','Рынок труда','E-commerce'].map(x=>`<option ${draft.category===x?'selected':''}>${x}</option>`).join('')}</select></label>`:step===2?`${field('actor','Идентификатор интеграции','партнёр/идентификатор',201)}<p class="fine">Служебное поле для подключения. Не попадёт в витрину покупателя. Не вводите пароли или API-ключи.</p>${field('inputExample','Пример входного задания','Например: категория товара, страна и лимит позиций',1000,true)}${field('outputFields','Что будет в результате?','Например: название товара, цена, валюта, ссылка, дата сбора',1000,true)}${field('limitations','Какие есть ограничения?','Какие данные недоступны, лимиты объёма и условия использования',1000,true)}`:`<dl class="draft-summary">${[['title','Продукт'],['audience','Для кого'],['description','Задача и результат'],['category','Категория'],['inputExample','Пример задания'],['outputFields','Поля результата'],['limitations','Ограничения']].map(([k,l])=>`<dt>${l}</dt><dd>${esc(draft[k])}</dd>`).join('')}</dl><div class="partner-notice">Это заявка на отбор, не договор о продажах. Команда проверит права, качество и себестоимость; коммерческие условия согласуются отдельно.</div>${user&&['supplier','operator'].includes(user.role)?'<label class="role-check"><input type="checkbox" name="confirmed" required>Я проверил описание и понимаю, что отправка заявки не публикует продукт автоматически.</label>':`<p class="fine">${user?'Вы вошли как покупатель. Для подачи заявки используйте аккаунт партнёра. Черновик сохранится в этой вкладке.':'Для отправки нужен аккаунт партнёра. Черновик сохранится, пока вы входите или регистрируетесь.'}</p>`}`;
 return `<section class="partner-wizard"><a class="quiet-link" href="#start/supplier">О сотрудничестве с Affsiwen</a><div class="overline">АНКЕТА ПАРТНЁРА</div><h1>${['Расскажите о продукте','Опишите вход и результат','Проверьте заявку'][step-1]}</h1><p>Сначала подготовим описание. После отправки вы сможете следить за статусом в кабинете.</p><div class="wizard-steps" aria-label="Этапы заявки">${['О продукте','Как работает','Проверка и отправка'].map((x,i)=>`<span class="${step===i+1?'current':''}" ${step===i+1?'aria-current="step"':''}>0${i+1} · ${x}</span>`).join('')}</div><div class="wizard-layout"><form id="partner-wizard" data-step="${step}" class="wizard-panel">${fields}<div class="actions">${step>1?'<button class="secondary" type="button" data-action="partner-back">Назад</button>':''}<button class="primary" type="submit">${step<3?'Продолжить':user&&['supplier','operator'].includes(user.role)?'Отправить на проверку':'Войти как партнёр'}</button></div><p class="fine">Черновик хранится в этой вкладке. Ключи доступа на этом этапе не нужны.</p></form><aside class="wizard-aside"><h3>${step===1?'Продаём понятный результат':step===2?'Проверяем, что можно выдать':'Что будет дальше'}</h3><p>${step===1?'Хорошее описание отвечает на два вопроса: кто покупатель и что он сможет сделать с полученными данными.':step===2?'Нужен пример, по которому команда сможет проверить продукт. Все ограничения лучше обозначить заранее.':'Заявка получит статус «На отборе». До решения оператора её не увидят покупатели.'}</p><ul><li>Ваш продукт не публикуется автоматически</li><li>Фиксированную долю выплат не обещаем</li><li>Условия и стоимость обсуждаются после проверки</li></ul><a class="quiet-link" href="#start/supplier">Все этапы сотрудничества</a></aside></div></section>`;
}
